from pathlib import Path

path = Path("apps/web/src/physics/GarmentXpbdAdapter.ts")
text = path.read_text(encoding="utf-8")
old = '''  for (const seam of state.stitchConstraints) {\n    appendPointReference(seamIndices, seamWeights, seam.a);\n    appendPointReference(seamIndices, seamWeights, seam.b);\n    const restDistance = Math.max(\n      0,\n      seam.slackMm * METERS_PER_MM / Math.max(1, seamGroupSampleCount(state, seam.seamGroupId)),\n    );\n    seamRestDistances.push(restDistance);\n    seamCompliances.push(seamCompliance(seam.treatment));\n    const initialResidual = Math.abs(pointReferenceDistance(state.positions, seam.a, seam.b) - restDistance);\n    seamRelaxations.push(\n      seam.instanceA !== undefined && seam.instanceA === seam.instanceB\n        ? 1\n        : initialResidual <= (options.config?.seamTolerance ?? DEFAULT_XPBD_CONFIG.seamTolerance)\n          ? 0.35\n          : 1,\n    );\n    seamGroupIds.push(seam.seamGroupId);\n  }\n'''
new = old + '''\n  // Keep the canonical assembly constraints first and index-aligned for the\n  // Prompt 10.3 adapter audit. Refine sewn darts only as additional XPBD\n  // constraints along both material legs.\n  for (const seam of state.stitchConstraints) {\n    if (seam.treatment !== "dart" || !seam.instanceA || seam.instanceA !== seam.instanceB) continue;\n    const instance = state.instances.find((candidate) => candidate.id === seam.instanceA);\n    const dartId = seam.seamGroupId.startsWith("dart:") ? seam.seamGroupId.slice(5) : "";\n    const dart = instance?.topology.darts.find((candidate) => candidate.dart.id === dartId)?.dart;\n    if (!instance || !dart) continue;\n    for (const pair of buildDartSeamChain(instance, dart)) {\n      appendPointReference(seamIndices, seamWeights, pair.first);\n      appendPointReference(seamIndices, seamWeights, pair.second);\n      seamRestDistances.push(0);\n      seamCompliances.push(seamCompliance("dart"));\n      seamRelaxations.push(1);\n      seamGroupIds.push(seam.seamGroupId);\n    }\n  }\n'''
if text.count(old) != 1:
    raise RuntimeError(f"canonical seam loop marker mismatch: {text.count(old)}")
text = text.replace(old, new, 1)
marker = '''function seamGroupSampleCount(state: GarmentAssemblyState, seamGroupId: string): number {\n'''
helper = '''function buildDartSeamChain(\n  instance: AssemblyPanelInstance,\n  dart: {\n    legA: { xMm: number; yMm: number };\n    legB: { xMm: number; yMm: number };\n    apex: { xMm: number; yMm: number };\n  },\n): Array<{ first: GlobalPointReference; second: GlobalPointReference }> {\n  const lengthA = Math.hypot(dart.apex.xMm - dart.legA.xMm, dart.apex.yMm - dart.legA.yMm);\n  const lengthB = Math.hypot(dart.apex.xMm - dart.legB.xMm, dart.apex.yMm - dart.legB.yMm);\n  const typicalEdgeMm = typicalPanelEdgeLengthMm(instance);\n  const sampleCount = clampInteger(\n    Math.ceil(Math.max(lengthA, lengthB) / Math.max(typicalEdgeMm, 1)),\n    2,\n    32,\n  );\n  const result: Array<{ first: GlobalPointReference; second: GlobalPointReference }> = [];\n  const seen = new Set<string>();\n  // sample=0 is the canonical dart-foot constraint; sampleCount is the common apex.\n  for (let sample = 1; sample < sampleCount; sample += 1) {\n    const t = sample / sampleCount;\n    const firstLocal = nearestMaterialVertex(\n      instance,\n      dart.legA.xMm + (dart.apex.xMm - dart.legA.xMm) * t,\n      dart.legA.yMm + (dart.apex.yMm - dart.legA.yMm) * t,\n    );\n    const secondLocal = nearestMaterialVertex(\n      instance,\n      dart.legB.xMm + (dart.apex.xMm - dart.legB.xMm) * t,\n      dart.legB.yMm + (dart.apex.yMm - dart.legB.yMm) * t,\n    );\n    if (firstLocal < 0 || secondLocal < 0 || firstLocal === secondLocal) continue;\n    const firstParticle = instance.particleStart + firstLocal;\n    const secondParticle = instance.particleStart + secondLocal;\n    const key = firstParticle < secondParticle\n      ? `${firstParticle}:${secondParticle}`\n      : `${secondParticle}:${firstParticle}`;\n    if (seen.has(key)) continue;\n    seen.add(key);\n    result.push({\n      first: { particleIndices: [firstParticle], weights: [1] },\n      second: { particleIndices: [secondParticle], weights: [1] },\n    });\n  }\n  return result;\n}\n\nfunction nearestMaterialVertex(\n  instance: AssemblyPanelInstance,\n  xMm: number,\n  yMm: number,\n): number {\n  let best = -1;\n  let bestDistance2 = Number.POSITIVE_INFINITY;\n  for (let local = 0; local < instance.vertexCount; local += 1) {\n    const dx = instance.topology.positions2DMm[local * 2] - xMm;\n    const dy = instance.topology.positions2DMm[local * 2 + 1] - yMm;\n    const distance2 = dx * dx + dy * dy;\n    if (distance2 < bestDistance2) {\n      bestDistance2 = distance2;\n      best = local;\n    }\n  }\n  return best;\n}\n\nfunction typicalPanelEdgeLengthMm(instance: AssemblyPanelInstance): number {\n  const values: number[] = [];\n  const seen = new Set<string>();\n  const triangles = instance.topology.triangles;\n  for (let offset = 0; offset < triangles.length; offset += 3) {\n    const vertices = [triangles[offset], triangles[offset + 1], triangles[offset + 2]];\n    for (let edge = 0; edge < 3; edge += 1) {\n      const first = vertices[edge];\n      const second = vertices[(edge + 1) % 3];\n      const key = first < second ? `${first}:${second}` : `${second}:${first}`;\n      if (seen.has(key)) continue;\n      seen.add(key);\n      const dx = instance.topology.positions2DMm[first * 2] - instance.topology.positions2DMm[second * 2];\n      const dy = instance.topology.positions2DMm[first * 2 + 1] - instance.topology.positions2DMm[second * 2 + 1];\n      const length = Math.hypot(dx, dy);\n      if (Number.isFinite(length) && length > 1e-6) values.push(length);\n    }\n  }\n  if (values.length === 0) return 10;\n  values.sort((left, right) => left - right);\n  return values[Math.floor(values.length * 0.5)] ?? values[0];\n}\n\n'''
if text.count(marker) != 1:
    raise RuntimeError(f"helper insertion marker mismatch: {text.count(marker)}")
path.write_text(text.replace(marker, helper + marker, 1), encoding="utf-8")
